package com.diegoramos.konatus.pesquisaeleitoral.dto;

import java.math.BigDecimal;
import java.util.UUID;

public record CandidateWeightedResultDTO(
        UUID candidateId,
        String candidateName,
        BigDecimal weightedPercentage
) {
}

package com.diegoramos.konatus.pesquisaeleitoral.dto;

import io.swagger.v3.oas.annotations.media.Schema;

import java.math.BigDecimal;
import java.util.UUID;

@Schema(description = "Percentual ponderado de um candidato na pesquisa")
public record CandidateWeightedResultDTO(
        @Schema(description = "ID do candidato", example = "11111111-1111-1111-1111-111111111111")
        UUID candidateId,
        @Schema(description = "Nome do candidato", example = "Maria Silva")
        String candidateName,
        @Schema(description = "Percentual ponderado final", example = "41.82")
        BigDecimal weightedPercentage
) {
}

package com.diegoramos.konatus.pesquisaeleitoral.dto.IbgeDTO;

public record IbgeSyncResultDTO(
        int statesCreated,
        int statesUpdated,
        int municipalitiesCreated,
        boolean forced
) {
}

package com.diegoramos.konatus.pesquisaeleitoral.dto.IbgeDTO;

import io.swagger.v3.oas.annotations.media.Schema;

@Schema(description = "Resumo da sincronizacao da base IBGE")
public record IbgeSyncResultDTO(
        @Schema(description = "Quantidade de estados criados", example = "0")
        int statesCreated,
        @Schema(description = "Quantidade de estados atualizados", example = "1")
        int statesUpdated,
        @Schema(description = "Quantidade de municipios criados", example = "0")
        int municipalitiesCreated,
        @Schema(description = "Indica se foi disparo manual forcado", example = "true")
        boolean forced
) {
}

package com.diegoramos.konatus.pesquisaeleitoral.dto.PollDTO;

import com.diegoramos.konatus.pesquisaeleitoral.dto.CandidateWeightedResultDTO;

import java.time.LocalDate;
import java.util.List;

public record PollImportResponseDTO(
        String pollId,
        LocalDate pollDate,
        long weightedPopulation,
        List<CandidateWeightedResultDTO> candidates
) {
}

package com.diegoramos.konatus.pesquisaeleitoral.dto.PollDTO;

import com.diegoramos.konatus.pesquisaeleitoral.dto.CandidateWeightedResultDTO;
import io.swagger.v3.oas.annotations.media.ArraySchema;
import io.swagger.v3.oas.annotations.media.Schema;

import java.time.LocalDate;
import java.util.List;

@Schema(description = "Resultado da importacao e consolidacao ponderada da pesquisa")
public record PollImportResponseDTO(
        @Schema(description = "Identificador da pesquisa", example = "PESQ-2026-01")
        String pollId,
        @Schema(description = "Data da pesquisa", example = "2026-03-01")
        LocalDate pollDate,
        @Schema(description = "Populacao total usada na ponderacao", example = "12700000")
        long weightedPopulation,
        @ArraySchema(schema = @Schema(implementation = CandidateWeightedResultDTO.class,
                description = "Resultados ponderados por candidato"))
        List<CandidateWeightedResultDTO> candidates
) {
}
